-- ============================================================================
-- ACADEMIC DEMO FIX: ADVANCE ORACLE IDENTITY GENERATORS AFTER SEEDED ROWS
-- ============================================================================
-- 02_seed_data.sql deliberately includes explicit primary-key values, so that
-- linked student/application/interview examples have stable IDs for the viva.
-- With GENERATED BY DEFAULT AS IDENTITY, explicitly inserted IDs do not
-- necessarily advance the underlying sequence.
--
-- START WITH LIMIT VALUE lets Oracle determine MAX(id) + increment, ensuring
-- that the next Add Student / Add Company / Add Application / Add Interview
-- operation generates a fresh ID instead of ORA-00001 (duplicate key).
--
-- Only run after the seed inserts. These statements do not delete or edit rows.
-- Requires Oracle Database identity column support (12c or newer).
-- ============================================================================
ALTER TABLE STUDENT MODIFY student_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE CERTIFICATION MODIFY certification_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE PROJECT MODIFY project_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE INTERNSHIP MODIFY internship_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE COMPANY MODIFY company_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE APPLICATION MODIFY application_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE INTERVIEW MODIFY interview_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE PLACEMENT MODIFY placement_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);

PROMPT Identity sequences aligned with demonstration data.
